<template><main class="library-page"><router-link :to="prefix+'/dashboard'">Back to My Dashboard</router-link><header><p>NEXT LEVEL UP</p><h1>Tutoring resource library</h1><p>General teaching materials stay private until staff review and publish them. Student work stays in its own Session Hub.</p></header><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><form @submit.prevent="upload"><h2>Add a private resource</h2><label>Title<input v-model="title" required maxlength="255"/></label><label>Subject<input v-model="subject" maxlength="128"/></label><label>Grade or level<input v-model="grade" maxlength="64"/></label><label>General worksheet PDF<input ref="fileInput" type="file" accept="application/pdf" required/></label><button :disabled="busy">Save private draft</button></form><section><h2>Resources</h2><p v-if="!resources.length">No resources yet.</p><article v-for="resource in resources" :key="resource.id"><div><strong>{{resource.title}}</strong><p>{{resource.subject}} · {{resource.grade}} · {{resource.status}}</p></div><button @click="preview(resource)">Review PDF</button><button v-if="canPublish&&resource.status==='draft'&&!resource.clientSpecific" @click="publishing=resource">Publish after review</button><button v-if="resource.ownerId===userId||canPublish" @click="archive(resource)">Archive</button></article></section><section v-if="publishing" class="publish-dialog" role="dialog" aria-modal="true" aria-label="Publish general tutoring material"><h2>Publish {{publishing.title}}?</h2><label><input type="checkbox" v-model="reviewed"/> I reviewed the source and confirm it contains general instructional content without learner information, private notes or completed learner answers.</label><button :disabled="!reviewed||busy" @click="publish">Publish for this organization’s tutors</button><button @click="publishing=null;reviewed=false">Cancel</button></section></main></template>
<script setup>
import {ref,computed,onMounted} from 'vue';
import {useRoute} from 'vue-router';
import {useAgencyStore} from '../../store/agency';
import {useAuthStore} from '../../store/auth';
import api from '../../services/api';
const route=useRoute(),agency=useAgencyStore(),auth=useAuthStore(),resources=ref([]),canPublish=ref(false),busy=ref(false),error=ref(''),notice=ref(''),title=ref(''),subject=ref(''),grade=ref(''),fileInput=ref(null),publishing=ref(null),reviewed=ref(false);
const userId=computed(()=>Number(auth.user?.id)),prefix=computed(()=>route.params.organizationSlug?'/'+route.params.organizationSlug:''),path=()=>'/tutoring-library/'+Number(agency.currentAgency?.id);
async function action(fn){busy.value=true;error.value='';try{await fn();}catch(e){error.value=e.response?.data?.error?.message||e.message;}finally{busy.value=false;}}
async function load(){const {data}=await api.get(path(),{skipGlobalLoading:true});resources.value=data.resources;canPublish.value=data.canPublish;}
async function upload(){await action(async()=>{const file=fileInput.value.files[0];if(!file)return;const form=new FormData();for(const [key,value]of Object.entries({title:title.value,subject:subject.value,grade:grade.value}))form.append(key,value);form.append('file',file);await api.post(path(),form,{skipGlobalLoading:true});title.value='';fileInput.value.value='';await load();notice.value='Private draft saved. Tutors can prepare a copy in an authorized Session Hub.';});}
async function publish(){await action(async()=>{await api.post(path()+'/'+publishing.value.id+'/publish',{reviewedGeneral:reviewed.value},{skipGlobalLoading:true});publishing.value=null;reviewed.value=false;await load();notice.value='General resource published for this organization.';});}
async function archive(resource){await action(async()=>{await api.delete(path()+'/'+resource.id,{skipGlobalLoading:true});await load();});}
async function preview(resource){const tab=window.open('about:blank','_blank');if(tab)tab.opener=null;await action(async()=>{const {data}=await api.get(path()+'/'+resource.id+'/file',{responseType:'blob',skipGlobalLoading:true});const url=URL.createObjectURL(data);if(tab)tab.location=url;else{const a=document.createElement('a');a.href=url;a.download='general-worksheet.pdf';a.click();}setTimeout(()=>URL.revokeObjectURL(url),60000);});if(error.value)tab?.close();}
onMounted(()=>action(load));
</script>
<style scoped>.library-page{max-width:1100px;padding:30px;margin:auto;font:15px/1.6 system-ui;color:#183a52}.library-page header{background:#173956;color:white;border-radius:15px;padding:24px;margin:16px 0}.library-page header h1{margin:3px 0;font-size:30px}.library-page header>p:first-child{font-size:11px;letter-spacing:.13em;color:#b5e5d5}.library-page form{border:1px solid #c5d9e1;padding:20px;border-radius:12px;display:grid;grid-template-columns:1fr 1fr;gap:12px}.library-page form h2{grid-column:1/-1}.library-page label{display:grid;gap:5px}.library-page input{padding:10px;border:1px solid #b2cbd8;border-radius:7px;font:inherit}.library-page button{border:1px solid #b2cbd8;background:white;color:#20445f;border-radius:7px;padding:9px 13px;font:inherit;cursor:pointer}.library-page article{border:1px solid #ccdde4;border-radius:10px;padding:16px;margin:10px 0;display:flex;align-items:center;gap:10px}.library-page article>div{margin-right:auto}.library-page article p{margin:5px 0;color:#5c7484}.publish-dialog{position:fixed;z-index:10001;top:20%;left:50%;transform:translateX(-50%);width:min(90%,500px);background:white;padding:24px;border-radius:14px;box-shadow:0 0 0 100vmax #0008}.publish-dialog label{display:block}.publish-dialog button{margin:12px 8px 0 0}.library-page [role=alert]{color:#a42c40}@media(max-width:650px){.library-page{padding:12px}.library-page form{grid-template-columns:1fr}.library-page article{flex-wrap:wrap}}
</style>
